function ocCalendar():array{static$c=null;if($c!==null)return$c;$list=ocGraph('GET','users/'.rawurlencode(CALENDAR_MAILBOX).'/calendars?$select=id,name,canEdit&$top=100');foreach(($list['value']??[])as$item)if(strcasecmp(trim((string)($item['name']??'')),CALENDAR_NAME)===0){if(($item['canEdit']??true)===false)throw new RuntimeException('Der Kalender „'.CALENDAR_NAME.'“ ist nicht bearbeitbar.');return$c=$item;}throw new RuntimeException('Der Zielkalender „'.CALENDAR_NAME.'“ wurde im Postfach '.CALENDAR_MAILBOX.' nicht gefunden.');}
function ocGoogleToken():string{static$t=null;if($t!==null)return$t;$svcJson=ocEnv('GOOGLE_DRIVE_SERVICE_ACCOUNT_JSON');if($svcJson!==''){if(!str_starts_with($svcJson,'{')){$decoded=base64_decode($svcJson,true);if($decoded!==false)$svcJson=$decoded;}$svc=json_decode($svcJson,true);if(is_array($svc)&&!empty($svc['client_email'])&&!empty($svc['private_key'])){$b64=fn(string$d)=>rtrim(strtr(base64_encode($d),'+/','-_'),'=');$now=time();$head=$b64(json_encode(['alg'=>'RS256','typ'=>'JWT']));$claims=$b64(json_encode(['iss'=>$svc['client_email'],'scope'=>'https://www.googleapis.com/auth/drive.readonly','aud'=>'https://oauth2.googleapis.com/token','iat'=>$now,'exp'=>$now+3500]));$input=$head.'.'.$claims;$sig='';if(openssl_sign($input,$sig,$svc['private_key'],OPENSSL_ALGO_SHA256)){$r=ocHttp('POST','https://oauth2.googleapis.com/token',['Content-Type: application/x-www-form-urlencoded'],http_build_query(['grant_type'=>'urn:ietf:params:oauth:grant-type:jwt-bearer','assertion'=>$input.'.'.$b64($sig)]));$j=json_decode($r['body'],true);if($r['status']===200&&!empty($j['access_token']))return$t=(string)$j['access_token'];}}}$client=ocEnv('GOOGLE_DRIVE_CLIENT_ID',ocSetting('google_drive_client_id'));$secret=ocEnv('GOOGLE_DRIVE_CLIENT_SECRET',ocSetting('google_drive_client_secret'));$refresh=ocEnv('GOOGLE_DRIVE_REFRESH_TOKEN',ocSetting('google_drive_refresh_token'));if($client!==''&&$secret!==''&&$refresh!==''){$r=ocHttp('POST','https://oauth2.googleapis.com/token',['Content-Type: application/x-www-form-urlencoded'],http_build_query(['client_id'=>$client,'client_secret'=>$secret,'refresh_token'=>$refresh,'grant_type'=>'refresh_token']));$j=json_decode($r['body'],true);if($r['status']===200&&!empty($j['access_token']))return$t=(string)$j['access_token'];}throw new RuntimeException('Google Drive ist nicht verbunden.');}
function ocDriveList(string $folderId):array{$q="'".str_replace("'","\\'",$folderId)."' in parents and trashed=false";$r=ocHttp('GET','https://www.googleapis.com/drive/v3/files?'.http_build_query(['q'=>$q,'fields'=>'files(id,name,mimeType,size,webViewLink)','pageSize'=>1000,'supportsAllDrives'=>'true']),['Authorization: Bearer '.ocGoogleToken()]);$j=json_decode($r['body'],true);if($r['status']!==200||!is_array($j))throw new RuntimeException('Fallunterlagen konnten nicht gelesen werden.');return is_array($j['files']??null)?$j['files']:[];}
