function ocDate(string $date,string $time):string{if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!preg_match('/^\d{2}:\d{2}$/',$time))throw new RuntimeException('Datum oder Uhrzeit ist ungültig.');return$date.'T'.$time.':00';}

