if($action==='create'){if($_SERVER['REQUEST_METHOD']!=='POST')apiError(405,'POST erforderlich.');$folderId=trim((string)($_POST['folder_id']??''));if($folderId==='')apiError(400,'Aktiver Fall fehlt.');$meta=ocMeta($folderId);if(!$meta)apiError(409,'Falldaten fehlen.');$date=(string)($_POST['date']??'');$time=(string)($_POST['time']??'');$start=ocDate($date,$time);$minutes=max(15,min(480,(int)($_POST['duration']??90)));$end=(new DateTime($start,new DateTimeZone('Europe/Berlin')))->modify('+'.$minutes.' minutes')->format('Y-m-d\TH:i:s');$address=trim(implode(' ',array_filter([(string)($meta['strasse']??''),(string)($meta['plz']??''),(string)($meta['ort']??'')])));if($address==='')throw new RuntimeException('Besichtigungsadresse fehlt in den Falldaten.');$caseNo=trim((string)($meta['schaden_nr']??''));$vn=trim((string)($meta['vn_objekt']??$meta['versicherungsnehmer']??''));$notes=trim((string)($_POST['notes']??''));$subject='Ortstermin'.($caseNo!==''?' · '.$caseNo:'').($vn!==''?' · '.$vn:'');$body='<p><strong>Schaden-Nr.:</strong> '.ocSafeHtml($caseNo).'<br><strong>VN / Objekt:</strong> '.ocSafeHtml($vn).'<br><strong>Besichtigungsadresse:</strong> '.ocSafeHtml($address).'<br><strong>Telefon:</strong> '.ocSafeHtml((string)($meta['telefon']??'')).'</p>'.($notes!==''?'<p><strong>Bemerkungen / Notizen:</strong><br>'.nl2br(ocSafeHtml($notes)).'</p>':'').'<p>Fallordner: <a href="https://drive.google.com/drive/folders/'.rawurlencode($folderId).'">Dokumente öffnen</a></p>';$attendees=[];$invite=($_POST['invite_vn']??'')==='1';$vnEmail=trim((string)($meta['email']??''));if($invite){if(!filter_var($vnEmail,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Für die Einladung fehlt eine gültige E-Mail-Adresse des VN.');$attendees[]=['emailAddress'=>['address'=>$vnEmail,'name'=>$vn?:$vnEmail],'type'=>'required'];}$calendar=ocCalendar();$event=ocGraph('POST','users/'.rawurlencode(CALENDAR_MAILBOX).'/calendars/'.rawurlencode((string)$calendar['id']).'/events',['subject'=>$subject,'bo